import collections, bisect
def closures(evs, W, lo, hi):
    # adjacency: for each node, list of (t, other)
    adj=collections.defaultdict(list)
    for u,v,t in evs:
        adj[u].append((t,v)); adj[v].append((t,u))
    for k in adj: adj[k].sort()
    res=[]
    for u,v,t in evs:
        if not (lo<=t<=hi): continue
        # find common contacts c with edges (u,c) and (v,c) both before t and within W
        cu={}
        for tt,c in adj[u]:
            if tt>=t: break
            if c!=v: cu[c]=tt
        for tt,c in adj[v]:
            if tt>=t: break
            if c!=u and c in cu:
                supp=max(cu[c],tt)
                if t-supp<=W and t-supp>=0:
                    res.append((u,v,t,c,supp,t-supp))
    return res
